SOURCE tests/procedures/support/fixture.sql;
INSERT INTO DB_User_Map(db_login,actor_type,customer_id) VALUES(USER(),'Customer',@p3_c1);
CALL sp_request_approval(@p3_a,@p3_b,100000,NULL,@p3_c1,@p3_approval);
DELETE FROM DB_User_Map WHERE db_login=USER();
CALL bank_lab.sp_expect_error(DATABASE(),'decide invalid decision','CALL {db}.sp_decide_approval(@p3_approval,''Approve'',@p3_m1,@p3_group)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'decide missing approval','CALL {db}.sp_decide_approval(-1,''Approved'',@p3_m1,@p3_group)',5007);
CALL bank_lab.sp_expect_error(DATABASE(),'decide wrong branch manager','CALL {db}.sp_decide_approval(@p3_approval,''Approved'',@p3_m2,@p3_group)',5010);
SET @p3_ok=(SELECT status='Requested' AND decided_by IS NULL FROM Transaction_Approvals WHERE approval_id=@p3_approval);
CALL bank_lab.sp_assert_true(DATABASE(),'decide failure stays Requested',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_error(DATABASE(),'decide Teller unauthorized','CALL {db}.sp_decide_approval(@p3_approval,''Approved'',@p3_t1,@p3_group)',5010);
SET @p3_old=(SELECT balance FROM Accounts WHERE account_id=@p3_a);
CALL bank_lab.sp_expect_ok(DATABASE(),'decide approved moves funds','CALL {db}.sp_decide_approval(@p3_approval,''Approved'',@p3_m1,@p3_group)');
SET @p3_ok=(SELECT status='Approved' AND resulting_transfer_group_id=@p3_group AND decided_by=@p3_m1 AND decided_at IS NOT NULL AND (SELECT balance FROM Accounts WHERE account_id=@p3_a)=@p3_old-100000 AND (SELECT COUNT(*) FROM Transactions WHERE transfer_group_id=@p3_group)=2 FROM Transaction_Approvals WHERE approval_id=@p3_approval);
CALL bank_lab.sp_assert_true(DATABASE(),'decide links group and money',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_error(DATABASE(),'decide twice','CALL {db}.sp_decide_approval(@p3_approval,''Approved'',@p3_m1,@p3_group)',5009);
INSERT INTO DB_User_Map(db_login,actor_type,customer_id) VALUES(USER(),'Customer',@p3_c1);
CALL sp_request_approval(@p3_a,@p3_b,100000,NULL,@p3_c1,@p3_approval);
DELETE FROM DB_User_Map WHERE db_login=USER();
SET @p3_old=(SELECT balance FROM Accounts WHERE account_id=@p3_a);
CALL bank_lab.sp_expect_ok(DATABASE(),'decide rejected','CALL {db}.sp_decide_approval(@p3_approval,''Rejected'',@p3_m1,@p3_group)');
SET @p3_ok=(SELECT status='Rejected' AND resulting_transfer_group_id IS NULL AND @p3_group IS NULL AND (SELECT balance FROM Accounts WHERE account_id=@p3_a)=@p3_old FROM Transaction_Approvals WHERE approval_id=@p3_approval);
CALL bank_lab.sp_assert_true(DATABASE(),'reject no movement',@p3_ok,'Expected procedure contract');
INSERT INTO DB_User_Map(db_login,actor_type,employee_id) VALUES(USER(),'Employee',@p3_m1);
CALL sp_request_approval(@p3_a,@p3_b,100000,@p3_m1,NULL,@p3_approval);
DELETE FROM DB_User_Map WHERE db_login=USER();
CALL bank_lab.sp_expect_error(DATABASE(),'decide requester cannot approve','CALL {db}.sp_decide_approval(@p3_approval,''Approved'',@p3_m1,@p3_group)',5010);
INSERT INTO DB_User_Map(db_login,actor_type,customer_id) VALUES(USER(),'Customer',@p3_c1);
CALL sp_request_approval(@p3_a,@p3_b,100000,NULL,@p3_c1,@p3_approval);
DELETE FROM DB_User_Map WHERE db_login=USER();
CALL sp_set_account_status(@p3_b,'Frozen',@p3_t2);
SET @p3_old=(SELECT balance FROM Accounts WHERE account_id=@p3_a);
CALL bank_lab.sp_expect_error(DATABASE(),'decide frozen destination rolls back','CALL {db}.sp_decide_approval(@p3_approval,''Approved'',@p3_m1,@p3_group)',5003);
SET @p3_ok=(SELECT status='Requested' AND (SELECT balance FROM Accounts WHERE account_id=@p3_a)=@p3_old FROM Transaction_Approvals WHERE approval_id=@p3_approval);
CALL bank_lab.sp_assert_true(DATABASE(),'decide failed transfer preserves approval',@p3_ok,'Expected procedure contract');
CALL sp_set_account_status(@p3_b,'Active',@p3_t2);

SOURCE tests/procedures/support/extra_11_sp_decide_approval.sql;
